insert into public.catalog_entries (id, kind, name, aliases, port, transport, description, blurb, answer_eligible, retired, sources) values
	('ftp', 'protocol', 'FTP', '{}'::text[], 21, 'tcp', 'FTP (File Transfer Protocol) is a client-server protocol for uploading and downloading files between hosts, using a separate control connection and data connection. It has used port 21 for control commands since the earliest Internet standards.', null, true, false, '[{"label":"RFC 959","url":"https://www.rfc-editor.org/rfc/rfc959"}]'::jsonb),
	('ssh', 'protocol', 'SSH', '{}'::text[], 22, 'tcp', 'SSH (Secure Shell) is a protocol for encrypted remote login and command execution between hosts, replacing Telnet for anything security-sensitive. IANA registered it on port 22 in 1995.', null, true, false, '[{"label":"RFC 4253","url":"https://www.rfc-editor.org/rfc/rfc4253"}]'::jsonb),
	('telnet', 'protocol', 'Telnet', '{}'::text[], 23, 'tcp', 'Telnet is a protocol for interactive, text-based remote terminal sessions over a network. It sends all traffic, including passwords, in plain text, which is why SSH has replaced it for anything security-sensitive.', null, true, false, '[{"label":"RFC 854","url":"https://www.rfc-editor.org/rfc/rfc854"}]'::jsonb),
	('smtp', 'protocol', 'SMTP', '{}'::text[], 25, 'tcp', 'SMTP (Simple Mail Transfer Protocol) is the protocol mail servers use to relay email to one another. Port 25 has been its standard server-to-server delivery port since the protocol was defined.', null, true, false, '[{"label":"RFC 5321","url":"https://www.rfc-editor.org/rfc/rfc5321"}]'::jsonb),
	('dns', 'protocol', 'DNS', '{}'::text[], 53, 'both', 'DNS (Domain Name System) translates human-readable domain names into IP addresses and other records. It mostly runs over UDP for speed on port 53, falling back to TCP for larger responses such as zone transfers.', null, true, false, '[{"label":"RFC 1035","url":"https://www.rfc-editor.org/rfc/rfc1035"}]'::jsonb),
	('dhcp', 'protocol', 'DHCP', '{}'::text[], 67, 'udp', 'DHCP (Dynamic Host Configuration Protocol) automatically assigns IP addresses and network settings to devices joining a network. Servers listen on port 67 while clients receive replies on port 68.', null, true, false, '[{"label":"RFC 2131","url":"https://www.rfc-editor.org/rfc/rfc2131"}]'::jsonb),
	('tftp', 'protocol', 'TFTP', '{}'::text[], 69, 'udp', 'TFTP (Trivial File Transfer Protocol) is a stripped-down file transfer protocol with no login or directory listing, commonly used to boot diskless devices and network hardware over UDP.', null, true, false, '[{"label":"RFC 1350","url":"https://www.rfc-editor.org/rfc/rfc1350"}]'::jsonb),
	('http', 'protocol', 'HTTP', '{}'::text[], 80, 'tcp', 'HTTP (Hypertext Transfer Protocol) is the request-response protocol that underlies the web, fetching pages, APIs, and other resources. Port 80 has been its default, unencrypted port since the web''s earliest days.', null, true, false, '[{"label":"RFC 9110","url":"https://www.rfc-editor.org/rfc/rfc9110"}]'::jsonb),
	('pop3', 'protocol', 'POP3', '{}'::text[], 110, 'tcp', 'POP3 (Post Office Protocol version 3) lets a mail client download messages from a server, typically removing them from the server afterward. IMAP has mostly replaced it because IMAP keeps mail synced across devices.', null, true, false, '[{"label":"RFC 1939","url":"https://www.rfc-editor.org/rfc/rfc1939"}]'::jsonb),
	('ntp', 'protocol', 'NTP', '{}'::text[], 123, 'udp', 'NTP (Network Time Protocol) synchronizes computer clocks over a network to a common reference time. It is one of the oldest Internet protocols still in wide use, with its design dating to the 1980s.', null, true, false, '[{"label":"RFC 5905","url":"https://www.rfc-editor.org/rfc/rfc5905"}]'::jsonb),
	('imap', 'protocol', 'IMAP', '{}'::text[], 143, 'tcp', 'IMAP (Internet Message Access Protocol) lets a mail client read and manage messages that stay stored on the server, keeping read state and folders synced across multiple devices.', null, true, false, '[{"label":"RFC 9051 (IMAP4rev2)","url":"https://www.rfc-editor.org/rfc/rfc9051"}]'::jsonb),
	('snmp', 'protocol', 'SNMP', '{}'::text[], 161, 'udp', 'SNMP (Simple Network Management Protocol) lets network devices such as routers and switches expose status and configuration data to monitoring tools. Agents listen for queries on port 161, and devices send unsolicited traps on port 162.', null, true, false, '[{"label":"RFC 3411 (SNMPv3 framework)","url":"https://www.rfc-editor.org/rfc/rfc3411"}]'::jsonb),
	('ldap', 'protocol', 'LDAP', '{}'::text[], 389, 'tcp', 'LDAP (Lightweight Directory Access Protocol) queries and modifies directory services such as user and group records. It is the protocol behind most enterprise identity systems, including Active Directory.', null, true, false, '[{"label":"RFC 4511","url":"https://www.rfc-editor.org/rfc/rfc4511"}]'::jsonb),
	('https', 'protocol', 'HTTPS', '{}'::text[], 443, 'tcp', 'HTTPS is HTTP carried over a TLS-encrypted connection, protecting requests and responses from eavesdropping and tampering. Port 443 became the default encrypted web port in the mid-1990s and now carries most web traffic.', null, true, false, '[{"label":"RFC 8446 (TLS 1.3)","url":"https://www.rfc-editor.org/rfc/rfc8446"}]'::jsonb),
	('smtps', 'protocol', 'SMTPS', '{}'::text[], 465, 'tcp', 'SMTPS is SMTP wrapped in an implicit TLS connection from the start, rather than upgrading mid-session with STARTTLS. Port 465 was reassigned to this purpose after RFC 8314 recommended implicit TLS for mail.', null, true, false, '[{"label":"RFC 8314","url":"https://www.rfc-editor.org/rfc/rfc8314"}]'::jsonb),
	('submission', 'protocol', 'Submission', '{}'::text[], 587, 'tcp', 'Message submission is the protocol a mail client uses to hand a new message to its own outgoing server, distinct from server-to-server relay on port 25. It typically requires authentication and STARTTLS on port 587.', null, true, false, '[{"label":"RFC 6409","url":"https://www.rfc-editor.org/rfc/rfc6409"}]'::jsonb),
	('ldaps', 'protocol', 'LDAPS', '{}'::text[], 636, 'tcp', 'LDAPS is LDAP wrapped in implicit TLS from the start of the connection, rather than upgrading via StartTLS on port 389. Port 636 is its dedicated encrypted directory-service port.', null, true, false, '[{"label":"Microsoft LDAPS docs","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/enable-ldap-over-ssl-3rd-certification-authority"}]'::jsonb),
	('imaps', 'protocol', 'IMAPS', '{}'::text[], 993, 'tcp', 'IMAPS is IMAP wrapped in implicit TLS from the start of the connection. Port 993 is its dedicated encrypted port, following the implicit-TLS guidance in RFC 8314.', null, true, false, '[{"label":"RFC 8314","url":"https://www.rfc-editor.org/rfc/rfc8314"}]'::jsonb),
	('pop3s', 'protocol', 'POP3S', '{}'::text[], 995, 'tcp', 'POP3S is POP3 wrapped in implicit TLS from the start of the connection. Port 995 is its dedicated encrypted port, following the same implicit-TLS guidance as IMAPS and SMTPS.', null, true, false, '[{"label":"RFC 8314","url":"https://www.rfc-editor.org/rfc/rfc8314"}]'::jsonb),
	('mysql', 'protocol', 'MySQL', '{}'::text[], 3306, 'tcp', 'MySQL is a relational database. Its server listens on port 3306 for the MySQL client protocol that drivers and command-line tools use to authenticate and run queries.', null, true, false, '[{"label":"MySQL docs","url":"https://dev.mysql.com/doc/refman/8.4/en/connecting.html"}]'::jsonb),
	('rdp', 'protocol', 'RDP', '{}'::text[], 3389, 'tcp', 'RDP (Remote Desktop Protocol) is Microsoft''s protocol for graphical remote access to a Windows machine''s desktop. It has used port 3389 since Windows NT 4.0 Terminal Server Edition.', null, true, false, '[{"label":"Microsoft: Understanding RDP","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/remote/understanding-remote-desktop-protocol"}]'::jsonb),
	('postgresql', 'protocol', 'PostgreSQL', array['postgres']::text[], 5432, 'tcp', 'PostgreSQL is a relational database. Its server listens on port 5432 for the frontend/backend protocol that clients use to authenticate, run queries, and stream results.', null, true, false, '[{"label":"PostgreSQL protocol docs","url":"https://www.postgresql.org/docs/current/protocol.html"}]'::jsonb),
	('vnc', 'protocol', 'VNC', '{}'::text[], 5900, 'tcp', 'VNC (Virtual Network Computing) shares a remote desktop''s screen and input over the RFB protocol. Its first display listens on port 5900, with each additional display adding one to the port number.', null, true, false, '[{"label":"RFC 6143 (RFB)","url":"https://www.rfc-editor.org/rfc/rfc6143"}]'::jsonb),
	('redis', 'protocol', 'Redis', '{}'::text[], 6379, 'tcp', 'Redis is an in-memory data store used as a cache, message broker, and fast key-value database. Port 6379 is its IANA-registered default, listed under the service name "redis".', null, true, false, '[{"label":"Redis docs","url":"https://redis.io/docs/latest/"},{"label":"IANA service names","url":"https://www.iana.org/assignments/service-names-port-numbers/service-names-port-numbers.xhtml"}]'::jsonb),
	('http-alt', 'protocol', 'HTTP-alt', '{}'::text[], 8080, 'tcp', 'HTTP-alt is the common fallback port for web servers and proxies when port 80 is unavailable or reserved, widely used for local development and alternate HTTP services. IANA registers 8080 under the service name "http-alt".', 'Common alternate web port.', true, false, '[{"label":"IANA service names","url":"https://www.iana.org/assignments/service-names-port-numbers/service-names-port-numbers.xhtml"}]'::jsonb),
	('kerberos', 'protocol', 'Kerberos', '{}'::text[], 88, 'both', 'Kerberos is a network authentication protocol that uses tickets issued by a trusted key distribution center, letting users and services prove their identity without sending passwords over the network.', null, true, false, '[{"label":"RFC 4120","url":"https://www.rfc-editor.org/rfc/rfc4120"}]'::jsonb),
	('bgp', 'protocol', 'BGP', '{}'::text[], 179, 'tcp', 'BGP (Border Gateway Protocol) is the routing protocol that exchanges reachability information between autonomous systems on the Internet. It is the protocol that decides how traffic crosses between ISPs.', null, true, false, '[{"label":"RFC 4271","url":"https://www.rfc-editor.org/rfc/rfc4271"}]'::jsonb),
	('irc', 'protocol', 'IRC', '{}'::text[], 6667, 'tcp', 'IRC (Internet Relay Chat) is a text-based, real-time group chat protocol organized around channels on a server. Port 6667 is its traditional, unencrypted default.', null, true, false, '[{"label":"RFC 2812","url":"https://www.rfc-editor.org/rfc/rfc2812"}]'::jsonb),
	('sip', 'protocol', 'SIP', '{}'::text[], 5060, 'both', 'SIP (Session Initiation Protocol) sets up, modifies, and tears down voice, video, and messaging sessions such as VoIP calls. It only handles the signaling; a separate protocol, RTP, carries the actual media.', null, true, false, '[{"label":"RFC 3261","url":"https://www.rfc-editor.org/rfc/rfc3261"}]'::jsonb),
	('mqtt', 'protocol', 'MQTT', '{}'::text[], 1883, 'tcp', 'MQTT is a lightweight publish-subscribe messaging protocol designed for constrained devices and unreliable networks, widely used in IoT. Port 1883 is its IANA-registered, unencrypted default.', null, true, false, '[{"label":"MQTT specification","url":"https://mqtt.org/mqtt-specification/"}]'::jsonb),
	('amqp', 'protocol', 'AMQP', '{}'::text[], 5672, 'tcp', 'AMQP (Advanced Message Queuing Protocol) is a message-queuing protocol for reliably routing messages between producers and consumers, used by brokers such as RabbitMQ. Port 5672 is its IANA-registered default.', null, true, false, '[{"label":"OASIS AMQP 1.0 overview","url":"https://docs.oasis-open.org/amqp/core/v1.0/os/amqp-core-overview-v1.0-os.html"},{"label":"RabbitMQ AMQP concepts","url":"https://www.rabbitmq.com/tutorials/amqp-concepts.html"}]'::jsonb),
	('git', 'protocol', 'Git', '{}'::text[], 9418, 'tcp', 'The Git protocol is a fast, unauthenticated transport for fetching from a repository served by `git daemon`. Git-over-SSH and Git-over-HTTPS, which add authentication, have largely superseded it.', null, true, false, '[{"label":"git-daemon docs","url":"https://git-scm.com/docs/git-daemon"}]'::jsonb),
	('rsync', 'protocol', 'Rsync', '{}'::text[], 873, 'tcp', 'Rsync synchronizes files and directories between systems, transferring only the changed portions of files to minimize bandwidth. Running as a standalone daemon, it listens on port 873.', null, true, false, '[{"label":"rsync docs","url":"https://download.samba.org/pub/rsync/rsync.1"}]'::jsonb),
	('nfs', 'protocol', 'NFS', '{}'::text[], 2049, 'both', 'NFS (Network File System) lets a client mount and use a remote directory as if it were local. Port 2049 has been its main port since early NFS versions; NFS version 4 consolidated its auxiliary services onto that one port too, no longer needing a separate port-mapper service.', null, true, false, '[{"label":"RFC 7530 (NFSv4)","url":"https://www.rfc-editor.org/rfc/rfc7530"}]'::jsonb),
	('smb', 'protocol', 'SMB', '{}'::text[], 445, 'tcp', 'SMB (Server Message Block) shares files, printers, and named pipes between Windows systems and compatible clients such as Samba. Port 445 carries SMB directly over TCP, replacing the older NetBIOS-based ports.', null, true, false, '[{"label":"Microsoft SMB overview","url":"https://learn.microsoft.com/en-us/windows-server/storage/file-server/file-server-smb-overview"}]'::jsonb),
	('iscsi', 'protocol', 'iSCSI', '{}'::text[], 3260, 'tcp', 'iSCSI (Internet Small Computer Systems Interface) carries SCSI storage commands over TCP/IP, letting a client mount a remote block device as if it were a local disk.', null, true, false, '[{"label":"RFC 7143","url":"https://www.rfc-editor.org/rfc/rfc7143"}]'::jsonb),
	('syslog', 'protocol', 'Syslog', '{}'::text[], 514, 'udp', 'Syslog is a standard for forwarding log messages from devices and applications to a central logging server. Port 514 is its traditional UDP port, though many deployments now use TLS on other ports for reliability and security.', null, true, false, '[{"label":"RFC 5424","url":"https://www.rfc-editor.org/rfc/rfc5424"}]'::jsonb),
	('radius', 'protocol', 'RADIUS', '{}'::text[], 1812, 'udp', 'RADIUS (Remote Authentication Dial-In User Service) centralizes authentication, authorization, and accounting for network access, commonly used by VPNs, Wi-Fi, and switches. Port 1812 replaced an earlier, conflicting port.', null, true, false, '[{"label":"RFC 2865","url":"https://www.rfc-editor.org/rfc/rfc2865"}]'::jsonb),
	('openvpn', 'protocol', 'OpenVPN', '{}'::text[], 1194, 'udp', 'OpenVPN is an open-source VPN protocol and software that tunnels traffic over an encrypted TLS connection. Port 1194 is its IANA-registered default, usually run over UDP.', null, true, false, '[{"label":"OpenVPN community docs","url":"https://openvpn.net/community-docs/"}]'::jsonb),
	('wireguard', 'protocol', 'WireGuard', '{}'::text[], 51820, 'udp', 'WireGuard is a modern VPN protocol built around a small codebase and current cryptography, tunneling traffic over UDP. Port 51820 is its conventional default, though it is not a formally registered IANA port.', null, true, false, '[{"label":"WireGuard quick start","url":"https://www.wireguard.com/quickstart/"}]'::jsonb),
	('echo', 'protocol', 'Echo', '{}'::text[], 7, 'tcp', 'The Echo protocol simply sends back whatever data it receives, historically used to test that a host is reachable and responsive. It predates ICMP ping as a connectivity check.', null, false, false, '[{"label":"RFC 862","url":"https://www.rfc-editor.org/rfc/rfc862"}]'::jsonb),
	('discard', 'protocol', 'Discard', '{}'::text[], 9, 'tcp', 'The Discard protocol silently drops any data sent to it, used historically to test outbound connectivity and to generate throwaway network traffic.', null, false, false, '[{"label":"RFC 863","url":"https://www.rfc-editor.org/rfc/rfc863"}]'::jsonb),
	('daytime', 'protocol', 'Daytime', '{}'::text[], 13, 'tcp', 'The Daytime protocol returns the current date and time as human-readable text when a client connects, a simple predecessor to NTP for checking a server''s clock.', null, false, false, '[{"label":"RFC 867","url":"https://www.rfc-editor.org/rfc/rfc867"}]'::jsonb),
	('chargen', 'protocol', 'chargen', '{}'::text[], 19, 'tcp', 'Character Generator (chargen) sends a continuous stream of test characters to any client that connects, historically used to test network throughput. It is now mostly disabled, since it has been abused to amplify UDP denial-of-service attacks.', null, false, false, '[{"label":"RFC 864","url":"https://www.rfc-editor.org/rfc/rfc864"}]'::jsonb),
	('whois', 'protocol', 'WHOIS', '{}'::text[], 43, 'tcp', 'WHOIS looks up registration information for a domain name or IP address block, such as its owner and registrar. It is a simple text query-response protocol with no built-in authentication.', null, false, false, '[{"label":"RFC 3912","url":"https://www.rfc-editor.org/rfc/rfc3912"}]'::jsonb),
	('gopher', 'protocol', 'Gopher', '{}'::text[], 70, 'tcp', 'Gopher is a menu-driven document retrieval protocol that predates the web, organizing content into hierarchical, text-based listings. HTTP and the web largely displaced it during the 1990s.', null, false, false, '[{"label":"RFC 1436","url":"https://www.rfc-editor.org/rfc/rfc1436"}]'::jsonb),
	('finger', 'protocol', 'Finger', '{}'::text[], 79, 'tcp', 'Finger returns information about a user on a remote system, such as their login name and last login time. It is rarely run today because it can leak personal and account details to anyone who asks.', null, false, false, '[{"label":"RFC 1288","url":"https://www.rfc-editor.org/rfc/rfc1288"}]'::jsonb),
	('ident', 'protocol', 'Ident', '{}'::text[], 113, 'tcp', 'Ident (the Identification Protocol) tells a remote server which local user owns a given TCP connection, historically used by IRC networks and mail servers to log or authenticate connecting users.', null, false, false, '[{"label":"RFC 1413","url":"https://www.rfc-editor.org/rfc/rfc1413"}]'::jsonb),
	('vite', 'application', 'Vite', '{}'::text[], 5173, 'tcp', 'Vite is a frontend build tool and development server that serves modules over native ES imports during development and bundles with Rollup for production. Its dev server defaults to port 5173.', 'Frontend bundler dev server', true, false, '[{"label":"Vite docs","url":"https://vite.dev/guide/"}]'::jsonb),
	('svelte', 'application', 'SvelteKit', '{}'::text[], 5173, 'tcp', 'SvelteKit is the official application framework built on Svelte, handling routing, server rendering, and bundling. Its dev server runs on Vite under the hood, which is why it shares Vite''s default port, 5173.', 'Full-stack app framework built on Vite', true, false, '[{"label":"SvelteKit docs","url":"https://svelte.dev/docs/kit/introduction"}]'::jsonb),
	('cra', 'application', 'Create React App', '{}'::text[], 3000, 'tcp', 'Create React App was Meta''s official, zero-config tool for scaffolding a React project, running a development server that defaulted to port 3000. The React team formally deprecated it in February 2025 in favor of tools like Vite.', 'Legacy React starter', true, false, '[{"label":"Create React App docs","url":"https://create-react-app.dev/"},{"label":"Sunsetting Create React App","url":"https://react.dev/blog/2025/02/14/sunsetting-create-react-app"}]'::jsonb),
	('next', 'application', 'Next.js', '{}'::text[], 3000, 'tcp', 'Next.js is a React framework providing server-side rendering, static generation, and file-based routing. Its development server defaults to port 3000, a default shared by several Node-based frameworks.', 'React meta-framework', true, false, '[{"label":"Next.js docs","url":"https://nextjs.org/docs"}]'::jsonb),
	('nuxt', 'application', 'Nuxt', '{}'::text[], 3000, 'tcp', 'Nuxt is a Vue framework offering server-side rendering, static generation, and file-based routing, playing a similar role for Vue that Next.js plays for React. Its dev server also defaults to port 3000.', 'Vue meta-framework', true, false, '[{"label":"Nuxt docs","url":"https://nuxt.com/docs"}]'::jsonb),
	('rails', 'application', 'Rails', '{}'::text[], 3000, 'tcp', 'Ruby on Rails is a full-stack web framework for Ruby. Its built-in server has defaulted to port 3000 since Rails'' earliest releases, a default many later frameworks copied.', 'Ruby web framework', true, false, '[{"label":"Rails guides","url":"https://guides.rubyonrails.org/"}]'::jsonb),
	('grafana', 'application', 'Grafana', '{}'::text[], 3000, 'tcp', 'Grafana is an observability platform for building dashboards from metrics, logs, and traces across many data sources. Its web UI defaults to port 3000, the same default several JavaScript dev servers also use.', 'Metrics dashboards', true, false, '[{"label":"Grafana docs","url":"https://grafana.com/docs/grafana/latest/"}]'::jsonb),
	('angular', 'application', 'Angular', '{}'::text[], 4200, 'tcp', 'Angular is a TypeScript-based frontend framework maintained by Google. Its CLI''s development server defaults to port 4200, a value set by the framework''s own convention.', null, true, false, '[{"label":"Angular CLI docs","url":"https://angular.dev/tools/cli/serve"}]'::jsonb),
	('astro', 'application', 'Astro', '{}'::text[], 4321, 'tcp', 'Astro is a frontend framework focused on shipping mostly static, content-driven sites with minimal client-side JavaScript. Its dev server defaults to port 4321, a playful rocket-countdown nod chosen by the project.', null, true, false, '[{"label":"Astro CLI reference","url":"https://docs.astro.build/en/reference/cli-reference/"}]'::jsonb),
	('flask', 'application', 'Flask', '{}'::text[], 5000, 'tcp', 'Flask is a lightweight Python web framework. Its built-in development server defaults to port 5000, which on modern macOS often conflicts with the built-in AirPlay Receiver service.', null, true, false, '[{"label":"Flask server docs","url":"https://flask.palletsprojects.com/en/stable/server/"}]'::jsonb),
	('django', 'application', 'Django', '{}'::text[], 8000, 'tcp', 'Django is a full-featured Python web framework. Its `runserver` development command defaults to port 8000, a common convention for Python web apps.', null, true, false, '[{"label":"Django runserver docs","url":"https://docs.djangoproject.com/en/stable/ref/django-admin/#runserver"}]'::jsonb),
	('webpack', 'application', 'webpack-dev-server', '{}'::text[], 8080, 'tcp', 'webpack-dev-server serves a webpack-bundled application and reloads it in the browser as source files change during development. It defaults to port 8080, one of the most common alternate HTTP ports.', 'Bundler dev server', true, false, '[{"label":"webpack-dev-server docs","url":"https://webpack.js.org/configuration/dev-server/"}]'::jsonb),
	('jenkins', 'application', 'Jenkins', '{}'::text[], 8080, 'tcp', 'Jenkins is an open-source automation server used to build, test, and deploy software through configurable pipelines. Its web UI defaults to port 8080, its long-standing installer default.', 'CI server', true, false, '[{"label":"Jenkins install docs","url":"https://www.jenkins.io/doc/book/installing/"}]'::jsonb),
	('tomcat', 'application', 'Tomcat', '{}'::text[], 8080, 'tcp', 'Apache Tomcat is a Java servlet container that runs Java web applications and JSPs. It has shipped with port 8080 as its default HTTP connector since its earliest releases.', 'Java servlet container', true, false, '[{"label":"Tomcat docs","url":"https://tomcat.apache.org/tomcat-10.1-doc/"}]'::jsonb),
	('storybook', 'application', 'Storybook', '{}'::text[], 6006, 'tcp', 'Storybook is a tool for building and testing UI components in isolation, outside a full application. Its dev server defaults to port 6006, a value the project chose with no special registry meaning.', null, true, false, '[{"label":"Storybook docs","url":"https://storybook.js.org/docs"}]'::jsonb),
	('kibana', 'application', 'Kibana', '{}'::text[], 5601, 'tcp', 'Kibana is the visualization and dashboard front end for Elasticsearch, letting users search, chart, and explore indexed data. Its web UI defaults to port 5601.', null, true, false, '[{"label":"Kibana settings docs","url":"https://www.elastic.co/guide/en/kibana/current/settings.html"}]'::jsonb),
	('elasticsearch', 'application', 'Elasticsearch', '{}'::text[], 9200, 'tcp', 'Elasticsearch is a distributed search and analytics engine. It exposes its REST API on port 9200 by default, with a separate port, 9300, reserved for inter-node cluster communication.', null, true, false, '[{"label":"Elasticsearch REST API docs","url":"https://www.elastic.co/guide/en/elasticsearch/reference/current/rest-apis.html"}]'::jsonb),
	('prometheus', 'application', 'Prometheus', '{}'::text[], 9090, 'tcp', 'Prometheus is a monitoring system that scrapes and stores time-series metrics from configured targets, with its own query language for alerting and dashboards. Its web UI and API default to port 9090.', null, true, false, '[{"label":"Prometheus docs","url":"https://prometheus.io/docs/introduction/overview/"}]'::jsonb),
	('consul', 'application', 'Consul', '{}'::text[], 8500, 'tcp', 'Consul is a service networking tool from HashiCorp providing service discovery, health checking, and a key-value store. Its HTTP API and web UI default to port 8500.', null, true, false, '[{"label":"Consul docs","url":"https://developer.hashicorp.com/consul/docs"}]'::jsonb),
	('vault', 'application', 'Vault', '{}'::text[], 8200, 'tcp', 'Vault is HashiCorp''s tool for securely storing and controlling access to secrets such as API keys, passwords, and certificates. Its API defaults to port 8200.', null, true, false, '[{"label":"Vault docs","url":"https://developer.hashicorp.com/vault/docs"}]'::jsonb),
	('minio', 'application', 'MinIO', '{}'::text[], 9000, 'tcp', 'MinIO is a self-hosted object storage server compatible with the Amazon S3 API, commonly used to run S3-style storage on-premises or in development, defaulting to port 9000 for that S3 API. MinIO Inc. discontinued the open-source project in 2026 in favor of its commercial AIStor product.', null, true, false, '[{"label":"MinIO GitHub","url":"https://github.com/minio/minio"}]'::jsonb),
	('rabbitmq-ui', 'application', 'RabbitMQ UI', '{}'::text[], 15672, 'tcp', 'RabbitMQ''s management plugin provides a web UI and HTTP API for monitoring and managing the message broker''s queues, exchanges, and connections. It listens on port 15672, separate from the broker''s own AMQP port, 5672.', null, true, false, '[{"label":"RabbitMQ management docs","url":"https://www.rabbitmq.com/docs/management"}]'::jsonb),
	('pgadmin', 'application', 'pgAdmin', '{}'::text[], 5050, 'tcp', 'pgAdmin is a web-based administration and query tool for PostgreSQL. The project''s official Docker image is commonly published to host port 5050 in its own setup examples, mapped to port 80 inside the container.', null, true, false, '[{"label":"pgAdmin container docs","url":"https://www.pgadmin.org/docs/pgadmin4/latest/container_deployment.html"}]'::jsonb),
	('docker', 'application', 'Docker API', '{}'::text[], 2375, 'tcp', 'The Docker Engine API lets clients and tools manage containers, images, and networks remotely. Port 2375 is its plain, unencrypted convention; Docker recommends port 2376 with TLS for anything beyond local testing.', null, true, false, '[{"label":"Docker remote access docs","url":"https://docs.docker.com/engine/daemon/remote-access/"}]'::jsonb),
	('kubernetes', 'application', 'Kubernetes API', '{}'::text[], 6443, 'tcp', 'The Kubernetes API server is the cluster''s control-plane front end, handling every read and write to cluster state. Port 6443 is its conventional secure default across most cluster setups.', null, true, false, '[{"label":"Kubernetes ports and protocols","url":"https://kubernetes.io/docs/reference/networking/ports-and-protocols/"}]'::jsonb),
	('mongo-express', 'application', 'mongo-express', '{}'::text[], 8081, 'tcp', 'mongo-express is a web-based admin UI for browsing and editing MongoDB databases and collections. Its default port, 8081, is set by the project''s own configuration.', null, false, false, '[{"label":"mongo-express GitHub","url":"https://github.com/mongo-express/mongo-express"}]'::jsonb);
